import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test(
    "a vendor cannot be renamed to another vendor's name, whatever the case",
    { tag: "@LIF-10" },
    async ({ apiAs }) => {
      // Arrange: two draft vendors with unique names owned by the member's tenant
      const member = await apiAs("member");
      const atlasName = uniqueName("Atlas Freight");
      const borealisName = uniqueName("Borealis Freight");

      const atlasResponse = await member.post("/api/vendors", {
        data: { name: atlasName, category: "logistics", contact_email: "ops@atlas.example.com" },
      });
      await expectStatus(atlasResponse, 201);

      const borealisResponse = await member.post("/api/vendors", {
        data: { name: borealisName, category: "logistics", contact_email: "ops@borealis.example.com" },
      });
      const borealis = await expectStatus<{ id: string; name: string }>(borealisResponse, 201);

      // Act: rename Borealis to Atlas's name in upper case
      const renameResponse = await member.patch(`/api/vendors/${borealis.id}`, {
        data: { name: atlasName.toUpperCase() },
      });

      // Assert: the rename is rejected with a name-taken conflict
      const body = await expectStatus<{ error: { code: string } }>(renameResponse, 409);
      expect(body.error.code).toBe("vendor_name_taken");

      // Assert: Borealis keeps its original name
      const current = await expectStatus<{ id: string; name: string }>(
        await member.get(`/api/vendors/${borealis.id}`),
        200,
      );
      expect(current.name).toBe(borealisName);
    },
  );
});
